/* Author-only GitHub media publishing. This module is never included in reader exports. */
const GH_MEDIA={repo:'chilitiancheng/novel-studio',branch:'main',prefix:'dist/media/',pages:'https://chilitiancheng.github.io/novel-studio/media/'};
let ghMediaToken='',ghMediaBusy=false,ghMediaAbort=null,ghMediaAuthEpoch=0;
function mediaStatus(message){document.getElementById('mediaStatus').textContent=message;}
function openMediaStudio(){document.getElementById('mediaStudio').hidden=false;document.getElementById('mediaStudio').scrollIntoView({block:'start',behavior:'smooth'});}
function requireGitHubMedia(){if(ghMediaToken)return true;openMediaStudio();mediaStatus('请先连接 GitHub。令牌只填在本页面，不要发到聊天里。');return false;}
async function ghMediaFetch(path,options={}){if(!ghMediaToken)throw Error('请先连接 GitHub');const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),120000);if(ghMediaAbort)ghMediaAbort.signal.addEventListener('abort',()=>controller.abort(),{once:true});try{const response=await fetch('https://api.github.com/repos/'+GH_MEDIA.repo+path,{...options,headers:{Accept:'application/vnd.github+json',Authorization:'Bearer '+ghMediaToken,'X-GitHub-Api-Version':'2022-11-28',...(options.headers||{})},signal:controller.signal,credentials:'omit',redirect:'error'});if(!response.ok)throw Error(response.status===401?'GitHub 令牌无效或已过期':response.status===403?'没有上传权限，请检查当前仓库的 Contents 读写权限':response.status===409?'仓库正在更新，请稍后重试':'GitHub 请求失败（HTTP '+response.status+'）');return await response.json();}finally{clearTimeout(timeout);}}
function bytesBase64(bytes){let result='';for(let i=0;i<bytes.length;i+=32768)result+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(result);}
async function inspectGitHubMedia(file){if(!file||!file.size)throw Error('请选择素材文件');if(file.size>20*1024*1024)throw Error('单个视频最多 20 MiB；图片和音乐最多 4 MiB');const bytes=new Uint8Array(await file.arrayBuffer()),text=(a,b)=>String.fromCharCode(...bytes.slice(a,b));let ext='',kind='',type='';if(bytes[0]===137&&text(1,4)==='PNG'){ext='png';kind='image';type='image/png';}else if(bytes[0]===255&&bytes[1]===216&&bytes[2]===255){ext='jpg';kind='image';type='image/jpeg';}else if(/^GIF8[79]a$/.test(text(0,6))){ext='gif';kind='image';type='image/gif';}else if(text(0,4)==='RIFF'&&text(8,12)==='WEBP'){ext='webp';kind='image';type='image/webp';}else if(text(4,8)==='ftyp'){if(file.type==='audio/mp4'||/\.m4a$/i.test(file.name)){ext='m4a';kind='audio';type='audio/mp4';}else{ext='mp4';kind='video';type='video/mp4';}}else if(text(0,3)==='ID3'||bytes[0]===255&&(bytes[1]&224)===224){ext='mp3';kind='audio';type='audio/mpeg';}else if(text(0,4)==='RIFF'&&text(8,12)==='WAVE'){ext='wav';kind='audio';type='audio/wav';}else if(text(0,4)==='OggS'){ext='ogg';kind='audio';type='audio/ogg';}if(!ext)throw Error('支持 JPG、PNG、GIF、WebP、MP4 视频及 MP3/M4A/WAV/OGG 音乐');if(kind!=='video'&&file.size>4*1024*1024)throw Error('图片和音乐最多 4 MiB，请压缩后再上传');if(kind==='image')await readImageFile(file);return {bytes,ext,kind,type};}
function video(text=''){return editBlock('video','视频',`<div class="picture-fields">${editField('','video-url','视频 MP4 直链 HTTPS')}<button data-action="upload-video" type="button">上传 MP4 到 GitHub 并填写</button><p class="flash-editor-note">视频用于 AO3，需读者点击播放；小红书 ZIP 不支持视频文件。</p></div>${editBody(paragraphs(text))}`);}
function renderVideo(source){const url=imageLink(fieldText(source,'video-url'));if(imageTarget==='mini')throw Error('小红书 ZIP 不支持视频文件，请先移除或替换视频节点；AO3 可使用视频直链。');if(imageTarget==='ao3'&&!url)throw Error('请上传 MP4 或填写视频 HTTPS 直链');return '<div class="video-scene">'+(url?'<video class="story-video" controls preload="none" playsinline src="'+esc(url)+'"></video>':'<div class="picture-empty">请上传 MP4 或填写视频直链</div>')+'<div class="picture-caption">'+partsHTML(renderParts(source.querySelector('[data-field=body]')))+'</div></div>';}
function appendVideoFields(fields,source){const label=document.createElement('label'),input=document.createElement('input');label.textContent='视频 MP4 直链 HTTPS';input.dataset.graphField='video-url';input.value=fieldText(source,'video-url');label.append(input);fields.append(label);appendGitHubUpload(fields,source,'video');const note=document.createElement('p');note.className='flash-editor-note';note.textContent='MP4 用于 AO3，点击播放；当前小红书 ZIP 不允许视频文件。';fields.append(note);}
function makeMediaAnchor(source,field){graphProjection(editor);return {work:book.id,chapter:book.active,node:source.dataset.nodeId,field};}
function fillMediaAnchor(anchor,url){let owner=anchor.work===book.id?book:workLibrary.get(anchor.work)?.book;if(!owner)return false;const chapter=owner.chapters.find(c=>c.id===anchor.chapter);if(!chapter)return false;let root,live=anchor.work===book.id&&anchor.chapter===book.active;if(live)root=editor;else{root=document.createElement('div');root.innerHTML=chapter.html;}const source=[...root.querySelectorAll('[data-node-id]')].find(el=>el.dataset.nodeId===anchor.node),field=source?.querySelector('[data-field="'+anchor.field+'"]');if(!field)return false;if(live)checkpoint();field.textContent=url;if(live){checkpoint();if(graphView)renderGraph(source);}else{chapter.html=root.innerHTML;if(anchor.work!==book.id){const record=workLibrary.get(anchor.work);if(record.book.active===chapter.id)record.html=chapter.html;record.savedAt=new Date().toISOString();}persist();}return true;}
function chooseAutoMediaTarget(info){let item=graphNodes.get(graphSelection),source=item?.kind==='effect'?item.source:null,field='';if(info.kind==='image'){if(source?.dataset.widget==='flash')field=info.ext==='gif'?'flash-gif-url':'image-url';else if(source?.dataset.widget==='image')field='image-url';else if(source?.dataset.widget==='player')field='cover-url';}else if(info.kind==='video'&&source?.dataset.widget==='video')field='video-url';else if(info.kind==='audio'&&source?.dataset.widget==='player')field='audio-url';if(field)return {source,field};const factory=info.kind==='image'?picture:info.kind==='video'?video:player;graphMutate(()=>{const div=document.createElement('div');div.innerHTML=factory('');source=div.firstElementChild;if(item?.kind==='choice')item.owner.prepend(source);else if(item?.source?.isConnected)item.source.after(source);else editor.append(source);graphExpanded.add(source);return source;});return {source,field:info.kind==='image'?'image-url':info.kind==='video'?'video-url':'audio-url'};}
async function mediaURLReady(url,type,signal){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);if(signal)signal.addEventListener('abort',()=>controller.abort(),{once:true});try{const response=await fetch(url+'?ready='+Date.now(),{method:'HEAD',cache:'no-store',credentials:'omit',signal:controller.signal});const mime=(response.headers.get('content-type')||'').toLowerCase();return response.ok&&(type.startsWith('image/')?mime.startsWith('image/'):type.startsWith('video/')?mime.startsWith('video/'):mime.startsWith('audio/'));}catch(error){return false;}finally{clearTimeout(timeout);}}
async function waitForMediaURL(url,type,signal){const end=Date.now()+240000;while(Date.now()<end){if(signal.aborted)throw Error('上传已取消；已提交的素材仍保留在 GitHub');if(await mediaURLReady(url,type,signal))return true;await new Promise(resolve=>setTimeout(resolve,3000));}return false;}
function mediaResult(url,anchor,type,ready){const row=document.createElement('div');row.className='media-result';const input=document.createElement('input');input.readOnly=true;input.value=url;input.setAttribute('aria-label','GitHub 素材直链');const state=document.createElement('span');state.textContent=ready?'直链已就绪':'已上传，等待 Pages 部署';const copy=document.createElement('button');copy.textContent='复制直链';copy.onclick=async()=>{try{await navigator.clipboard.writeText(url);state.textContent='已复制';}catch{input.select();state.textContent='请复制选中的链接';}};const apply=document.createElement('button');apply.textContent='检查并填写';apply.onclick=async()=>{apply.disabled=true;try{if(!await mediaURLReady(url,type))return state.textContent='部署尚未就绪，请稍后重试';state.textContent=fillMediaAnchor(anchor,url)?'已填写到原作品节点':'原节点已删除，请复制直链手动填写';}finally{apply.disabled=false;}};row.append(input,state,copy,apply);document.getElementById('mediaResults').prepend(row);return state;}
async function uploadGitHubMedia(file,target=null){if(!workLibraryReady)return mediaStatus('工作台正在恢复草稿，请稍候再上传');if(!requireGitHubMedia())return;if(ghMediaBusy)return mediaStatus('已有素材正在上传或等待部署，请稍候');ghMediaBusy=true;ghMediaAbort=new AbortController();const signal=ghMediaAbort.signal;document.getElementById('mediaUpload').disabled=true;let committed=false;try{mediaStatus('正在读取素材…');const info=await inspectGitHubMedia(file);if(signal.aborted||!ghMediaToken)throw Error('上传已取消');if(!target)target=chooseAutoMediaTarget(info);if(!target.source?.isConnected)throw Error('目标节点已移除，请重新选择');if(info.kind==='image'&&target.field==='image-url'&&target.source.querySelector('[data-field=image-asset]'))await attachPictureFile(target.source,file);const anchor=makeMediaAnchor(target.source,target.field),name='media-'+Date.now().toString(36)+'-'+(crypto.randomUUID?crypto.randomUUID().replace(/-/g,''):Math.random().toString(36).slice(2)+Math.random().toString(36).slice(2))+'.'+info.ext,path=GH_MEDIA.prefix+name;mediaStatus('正在上传到 GitHub…');await ghMediaFetch('/contents/'+path,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:'Upload story media '+name,branch:GH_MEDIA.branch,content:bytesBase64(info.bytes)})});committed=true;const url=GH_MEDIA.pages+name,state=mediaResult(url,anchor,info.type,false);mediaStatus('已上传，正在等待 GitHub Pages 部署（可能需要几分钟）。就绪后自动填写，请先不要刷新本页。');const ready=await waitForMediaURL(url,info.type,signal);if(ready){const filled=fillMediaAnchor(anchor,url);state.textContent=filled?'直链已就绪，已自动填写到原节点':'直链已就绪；原节点已移除，请复制后手动填写';mediaStatus(filled?'上传成功，直链已自动填写。':'上传成功，可复制素材直链。');}else mediaStatus('GitHub 已保存素材，Pages 部署尚未就绪。稍后可点「检查并填写」。');}catch(error){mediaStatus((committed?'素材已提交至 GitHub；':'')+(error.name==='AbortError'?'网络超时或已取消，请检查 GitHub 后再重试':error.message||'上传失败'));}finally{ghMediaBusy=false;ghMediaAbort=null;document.getElementById('mediaUpload').disabled=false;}}
function pickGitHubMedia(source,field,accept){if(!requireGitHubMedia())return;const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=()=>{if(input.files[0])uploadGitHubMedia(input.files[0],{source,field});};input.click();}
function appendGitHubUpload(fields,source,kind){const button=document.createElement('button');button.type='button';button.textContent=kind==='flash'?'生成 GIF → GitHub → 自动填写':kind==='image'?'上传图片 → GitHub → 自动填写':kind==='video'?'上传 MP4 → GitHub → 自动填写':'上传音乐 → GitHub → 自动填写';button.onclick=async()=>{if(!requireGitHubMedia())return;if(kind==='flash'){try{const blob=await makeFlashGIF(source);await uploadGitHubMedia(new File([blob],'flash.gif',{type:'image/gif'}),{source,field:'flash-gif-url'});}catch(error){mediaStatus(error.message);}}else if(kind==='image'){const asset=imageAssets[fieldText(source,'image-asset')];if(asset){const bytes=Uint8Array.from(atob(asset.data),c=>c.charCodeAt(0));uploadGitHubMedia(new File([bytes],asset.name,{type:asset.type}),{source,field:'image-url'});}else pickGitHubMedia(source,'image-url','.png,.jpg,.jpeg,.gif,.webp');}else if(kind==='video')pickGitHubMedia(source,'video-url','.mp4');else{const asset=musicAssets[fieldText(source,'audio-url').replace(/^paper-audio:/,'')];if(asset)uploadGitHubMedia(new File([Uint8Array.from(atob(asset.data),c=>c.charCodeAt(0))],asset.name,{type:asset.type}),{source,field:'audio-url'});else pickGitHubMedia(source,'audio-url','.mp3,.m4a,.wav,.ogg');}};fields.append(button);}
document.getElementById('openMediaStudio').onclick=openMediaStudio;
document.getElementById('closeMediaStudio').onclick=()=>document.getElementById('mediaStudio').hidden=true;
document.getElementById('mediaConnect').onclick=async()=>{const input=document.getElementById('githubMediaToken'),token=input.value.trim();input.value='';if(!token)return mediaStatus('请在本页输入 GitHub 上传令牌');const epoch=++ghMediaAuthEpoch;ghMediaToken=token;document.getElementById('mediaConnect').disabled=true;try{const repo=await ghMediaFetch('');if(epoch!==ghMediaAuthEpoch)return;if(repo.full_name!==GH_MEDIA.repo||repo.private)throw Error('目标仓库不匹配或不是公开仓库');mediaStatus('已连接 GitHub，可以选择素材上传。令牌不会随草稿或 ZIP 保存。');document.getElementById('mediaConnection').textContent='已连接';}catch(error){if(epoch!==ghMediaAuthEpoch)return;ghMediaToken='';document.getElementById('mediaConnection').textContent='未连接';mediaStatus(error.message);}finally{document.getElementById('mediaConnect').disabled=false;}};
document.getElementById('mediaDisconnect').onclick=()=>{ghMediaAuthEpoch++;ghMediaToken='';if(ghMediaAbort)ghMediaAbort.abort();document.getElementById('githubMediaToken').value='';document.getElementById('mediaConnection').textContent='未连接';mediaStatus('已断开授权；GitHub 中已经上传的素材会保留。');};
document.getElementById('mediaUpload').onclick=()=>{const file=document.getElementById('mediaFile').files[0];if(!file)return mediaStatus('请先选择素材，或拖入下方区域');uploadGitHubMedia(file);};
const mediaDrop=document.getElementById('mediaDrop');mediaDrop.addEventListener('dragover',event=>event.preventDefault());mediaDrop.addEventListener('drop',event=>{event.preventDefault();const file=event.dataTransfer.files[0];if(file)uploadGitHubMedia(file);});
document.addEventListener('click',event=>{const button=event.target.closest('[data-action=upload-video]');if(button)pickGitHubMedia(button.closest('[data-widget=video]'),'video-url','.mp4');});
window.addEventListener('pagehide',()=>{ghMediaAuthEpoch++;ghMediaToken='';if(ghMediaAbort)ghMediaAbort.abort();document.getElementById('githubMediaToken').value='';});

window.addEventListener('pageshow',()=>{if(!ghMediaToken)document.getElementById('mediaConnection').textContent='未连接';});
